def priority(task, state, k=0.5, m=2.0, alpha=0.3):
    slack = max(0.0, task.due - task.estimated_runtime - state.now)
    atc = task.weight / max(task.estimated_runtime, 1e-6) * math.exp(-slack / (k * max(state.mean_est, 1e-6)))
