def priority(task, state, k=1.0, m=2.0, stage_w=1.0):
    # Stage-aware ATC: urgency weighted by deadline-miss cost of task type
    slack = max(0.0, task.due - task.estimated_runtime - state.now)
    tier = m if task.tenant == 'premium' else 1.0
    if task.task_type == 'variant_calling':
        stage = 5.0
    elif task.task_type == 'sv_calling':
        stage = 3.0
    else:
        stage = 1.0
    stage_factor = 1.0 + stage_w * stage
    return tier * stage_factor * task.weight / max(task.estimated_runtime, 1e-6) * math.exp(-slack / (k * max(state.mean_est, 1e-6)))  # tuned (k=0.369,m=1.48,stage_w=3.79)

def priority(task, state, k=2.0, m=2.0, tight=0.5, type_w=1.0, type_v=3.0, type_s=2.0, cap=4.0):
    import math
    slack = max(0.0, task.due - task.estimated_runtime - state.now)
    tier = m if task.tenant == 'premium' else 1.0
    if task.task_type == 'variant_calling':
        tw = type_v
    elif task.task_type == 'sv_calling':
        tw = type_s
    else:
        tw = type_w
    wait = state.now - task.release
    aging = min(cap, wait / max(task.estimated_runtime, 1e-6))
