        urgent = max(urgent, 1.0)
    return tier * tw * task.weight / max(task.estimated_runtime, 1e-6) * urgent * (1.0 + aging)  # tuned (k=0.775,m=0.528,tight=0.549,type_w=0.458,type_v=5.76,type_s=4.52,cap=1.43)

def priority(task, state, k=1.0, eps=1e-6):
    import math
    slack = task.due - state.now - task.estimated_runtime
    w = 5.0 if task.task_type == 'variant_calling' else (3.0 if task.task_type == 'sv_calling' else 1.0)
