    if slack <= 0:
        return 1e9 + risk
    return risk * math.exp(-slack / max(k * state.mean_est, eps))  # tuned (k=0.616,eps=4.59e-07)

import math
def priority(task, state):
    # Stage-weighted urgency: due-time slack vs estimated runtime,
    # penalize long jobs slightly to improve packing under backfilling.
    stage_cost = {'variant_calling': 5.0, 'sv_calling': 3.0, 'alignment': 1.0}
    w = stage_cost.get(task.task_type, 1.0)
    slack = task.due - state.now - task.estimated_runtime
    urgency = w / max(slack, 1e-6) if slack > 0 else w * (1.0 + (state.now - task.due) / max(task.estimated_runtime, 1e-6))
    return urgency / max(task.estimated_runtime, 1e-6)

def priority(task, state, k=1.0, m=3.0, g=0.5):
    est = max(task.estimated_runtime, 1e-6)
    slack = task.due - state.now - est
    tier = m if task.tenant == 'premium' else 1.0
    stage = {'variant_calling': 5.0, 'sv_calling': 3.0, 'alignment': 1.0}.get(task.task_type, 1.0)
    load = state.queue_work / max(state.capacity, 1e-6)
    if slack <= g * est:
        return 1e6 * stage * tier + 1.0 / est
    atc = tier * task.weight / est * math.exp(-max(0.0, slack) / max(k * state.mean_est, 1e-6))
    return stage * atc * (1.0 + load)  # tuned (k=2.78,m=2.06,g=1.86)

def priority(task, state, guard_c=2.0, m=5.0, k=1.0, type_boost=2.0, congestion_thresh=0.5):
    est = max(task.estimated_runtime, 1e-6)
    wait = state.now - task.release
    ratio = wait / est
    if ratio >= guard_c:
        return 1e6 + task.weight / est
    slack = max(0.0, task.due - state.now - est)
    tier = m if task.tenant == 'premium' else 1.0
    type_weight = {'alignment': 1.0, 'variant_calling': type_boost * 5.0, 'sv_calling': type_boost * 3.0}.get(task.task_type, 1.0)
    congestion = state.queue_work / max(state.capacity, 1e-6)
    if congestion > congestion_thresh:
        return tier * type_weight * task.weight / est * math.exp(-slack / (k * max(state.mean_est, 1e-6)))
    return tier * type_weight / est  # tuned (guard_c=4.61,m=5.24,k=0.279,type_boost=5.02,congestion_thresh=1.22)

