def priority(task, state, k=1.0, m=2.0, q_thresh=0.5, boost=3.0):
    est = max(task.estimated_runtime, 1e-6)
    slack = max(0.0, task.due - est - state.now)
    tier = m if task.tenant == 'premium' else 1.0
    type_mult = 1.0
    if task.task_type == 'variant_calling':
        type_mult = 2.0
    elif task.task_type == 'sv_calling':
        type_mult = 1.5
    load = state.queue_work / max(state.capacity * max(state.mean_est, 1e-6), 1e-6)
    overload = 1.0 + boost * max(0.0, load - q_thresh)
    urgency = math.exp(-slack / (k * max(state.mean_est, 1e-6)))
    return tier * type_mult * overload * task.weight / est * urgency  # tuned (k=1.36,m=1.1,q_thresh=0.584,boost=5.73)

def priority(task, state, k=1.0, m=2.0, b=0.4, s=1.0, d=0.5):
    slack = max(0.0, task.due - task.estimated_runtime - state.now)
    tier = m if task.tenant == 'premium' else 1.0
    wait = state.now - task.release
    atc = tier * task.weight / max(task.estimated_runtime, 1e-6) * math.exp(-slack / (k * max(state.mean_est, 1e-6)))
    age = 1.0 + b * wait / max(task.estimated_runtime, 1e-6)
    stage_bonus = 1.0
    if task.task_type == 'variant_calling':
        stage_bonus = 1.0 + s
    elif task.task_type == 'sv_calling':
        stage_bonus = 1.0 + s * 0.6
    elif task.task_type == 'alignment':
        stage_bonus = 1.0 + s * 0.2
    urgency = 1.0 + d * max(0.0, task.estimated_runtime - slack) / max(task.estimated_runtime, 1e-6)
    return atc * age * stage_bonus * urgency  # tuned (k=1.29,m=0.711,b=1.35,s=3.19,d=0.175)

def priority(task, state, base_tier=2.0, sv_boost=0.8, variant_boost=1.8, pressure_scale=0.5):
    slack = max(0.0, task.due - task.estimated_runtime - state.now)
    tier = base_tier if task.tenant == 'premium' else 1.0
    atc = tier * task.weight / max(task.estimated_runtime, 1e-6) * math.exp(-slack / max(state.mean_est, 1e-6))
    type_mult = 1.0
    if task.task_type == 'variant_calling':
