    elif task.task_type == 'sv_calling':
        type_mult += sv_boost
    queue_pressure = state.queue_work / max(state.capacity * state.mean_est, 1e-6)
    pressure_mult = 1.0 + pressure_scale * queue_pressure
    return atc * type_mult * pressure_mult  # tuned (base_tier=1.12,sv_boost=0.421,variant_boost=1.24,pressure_scale=0.964)

def priority(task, state, k=1.0, m=2.0, cost_mult=2.0):
