    atc = tier * task.weight * (cw ** cost_mult) / est * math.exp(-slack / (k * max(state.mean_est, 1e-6)))
    # SPT component for short jobs
    spt = 1.0 / est
    return atc + spt  # tuned (k=0.366,m=3.11,cost_mult=0.828)

